export default {"html":"<p data-line=\"0\" class=\"code-line\">Angular Signal effects are handy: they run whenever Signals used inside the effect change.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"2\"><span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'signal variable is changed to '</span><span style=\"color:#F97583\"> +</span><span style=\"color:#B392F0\"> signalVariable</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"8\" class=\"code-line\">That works when the Signal is read on the first pass, but reads inside async code or conditionals are skipped.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"10\"><span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Runs whenever this.count changes</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  this</span><span style=\"color:#E1E4E8\">.insideSimpleEffect </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"17\"><span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Does not run</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  await</span><span style=\"color:#F97583\"> new</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">void</span><span style=\"color:#E1E4E8\">&gt;((</span><span style=\"color:#FFAB70\">resolve</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#B392F0\"> resolve</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  this</span><span style=\"color:#E1E4E8\">.insideAwaitRequestAnimationFrame </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Does not run</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  requestAnimationFrame</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.insideRequestAnimationFrame </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Does not run</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  setTimeout</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.insideSetTimeout </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }, </span><span style=\"color:#79B8FF\">100</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Does not run</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.insideSimpleEffect </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> 5</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.insideCondition </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"43\" class=\"code-line\">You can confirm they do not run at <a href=\"https://stackblitz.com/edit/stackblitz-starters-unvngn?file=src%2Fmain.ts\" target=\"_blank\" rel=\"noopener noreferrer\">https://stackblitz.com/edit/stackblitz-starters-unvngn?file=src%2Fmain.ts</a>.</p>\n<h2 id=\"cause\" data-line=\"45\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#cause\" aria-hidden=\"true\"></a> Cause</h2>\n<p data-line=\"47\" class=\"code-line\">Effects register dependencies only when a Signal is actually read. If a read is hidden in a conditional or happens on another stack frame in async work, the effect cannot register the dependency, so it will not react when the Signal changes.</p>\n<p data-line=\"49\" class=\"code-line\">Source: <a href=\"https://github.com/angular/angular/issues/56773#issuecomment-2198479276\" target=\"_blank\" rel=\"noopener noreferrer\">https://github.com/angular/angular/issues/56773#issuecomment-2198479276</a></p>\n<h2 id=\"mitigation\" data-line=\"51\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#mitigation\" aria-hidden=\"true\"></a> Mitigation</h2>\n<h3 id=\"1.-assign-on-the-first-line-always\" data-line=\"53\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#1.-assign-on-the-first-line-always\" aria-hidden=\"true\"></a> 1. Assign on the first line always</h3>\n<p data-line=\"55\" class=\"code-line\">To register dependencies, assign from every Signal you use on the first line. Simplest approach, but easy to miss because it depends on the author’s attention.</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"57\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span> effect(() =&gt; {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   const count = this.count();</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   if (this.insideSimpleEffect === 5) {</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>     this.insideCondition = this.count();</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     this.insideCondition = count;</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span> });</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><h3 id=\"2.-use-an-iife\" data-line=\"67\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#2.-use-an-iife\" aria-hidden=\"true\"></a> 2. Use an IIFE</h3>\n<p data-line=\"69\" class=\"code-line\">In an effect, call an IIFE and pass Signals as arguments to register dependencies. I prefer this—it makes the effect’s purpose clearer.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"71\"><span class=\"line\"><span style=\"color:#B392F0\">effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> ((</span><span style=\"color:#FFAB70\">count</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> number</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.insideSimpleEffect </span><span style=\"color:#F97583\">===</span><span style=\"color:#79B8FF\"> 5</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.insideCondition </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> count;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">count</span><span style=\"color:#E1E4E8\">()));</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"summary\" data-line=\"79\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"81\" class=\"code-line\">Signals are very ergonomic, especially for form change detection. Without understanding this behavior, they become a source of bugs, so I recommend codifying rules for how you use them.</p>\n<p data-line=\"83\" class=\"code-line\">See you next time.</p>\n","headings":[{"id":"cause","text":"Cause","level":2},{"id":"mitigation","text":"Mitigation","level":2},{"id":"1.-assign-on-the-first-line-always","text":"1. Assign on the first line always","level":3},{"id":"2.-use-an-iife","text":"2. Use an IIFE","level":3},{"id":"summary","text":"Summary","level":2}]} as const;
